shards = ["shard_001", "shard_002", "shard_003"]
done = {"shard_001", "shard_002"}
ran = []

def is_done(shard):
    return shard in done

def run_shard(shard):
    ran.append(shard)

for shard in shards:
    if is_done(shard):
        continue
    run_shard(shard)

print(ran)

